from dataclasses import dataclass
from typing import Any, List, Dict, Optional, Union

@dataclass
class TaskResult:
    status: str
    result: Optional[Any] = None
    error: Optional[str] = None
    func_name: Optional[str] = None

class TaskRunner:
    def __init__(self):
        self.tasks = []
        self._results: List[TaskResult] = []

    def add_task(self, func, *args, **kwargs) -> None:
        self.tasks.append((func, args, kwargs))

    def run(self) -> List[TaskResult]:
        self._results = []
        for func, args, kwargs in self.tasks:
            try:
                result = func(*args, **kwargs)
                self._results.append(TaskResult('ok', result=result))
            except Exception as e:
                self._results.append(TaskResult(
                    'error',
                    error=str(e),
                    func_name=func.__name__
                ))
        return self._results

    def get_errors(self) -> List[TaskResult]:
        return [r for r in self._results if r.status == 'error']

    def get_successes(self) -> List[TaskResult]:
        return [r for r in self._results if r.status == 'ok']

    @property
    def summary(self) -> Dict[str, int]:
        return {
            'success': sum(1 for r in self._results if r.status == 'ok'),
            'error': sum(1 for r in self._results if r.status == 'error')
        }
